  {$group: {_id: {from:'$raw.date_id_from',to:'$raw.date_id_to',cluster:'$raw.cluster',specialty:'$raw.specialty',category:'$raw.Category',description:'$raw.Description'}, raw:{$first:'$raw'}}},
  {$project: {_id:0, raw:1}}
], {maxTimeMS:10000}];
return msg;

const rows = (Array.isArray(msg.payload) ? msg.payload : []).map(r=>r.raw).filter(r=>r && r.specialty && r.cluster && r.date_id_from && r.date_id_to);
